<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('suppliers.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'suppliers');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){if(fpost('action')==='create'){$q=$pdo->prepare('INSERT INTO suppliers(supplier_code,company_name,contact_person,phone,email,address,payment_terms,lead_time_days,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([op_code('SUP'),fpost('company_name'),fpost('contact_person')?:null,fpost('phone')?:null,fpost('email')?:null,fpost('address')?:null,fpost('payment_terms')?:null,fint('lead_time_days'),fpost('notes')?:null,$staff['id']]);flash('success','Supplier created.');}staff_redirect('staff/pages/suppliers.php');}
$rows=db_rows($pdo,'SELECT s.*,(SELECT COUNT(*) FROM purchase_orders p WHERE p.supplier_id=s.id) po_count FROM suppliers s ORDER BY s.company_name');$pageTitle='Suppliers';require __DIR__.'/../../includes/staff/header.php';module_head('Procurement','Suppliers','Keep supplier contacts, lead times and purchasing history together.');?>
<div class="split-grid"><section class="staff-panel"><h2>Add supplier</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Company<input name="company_name" required></label><div class="two"><label>Contact<input name="contact_person"></label><label>Phone<input name="phone"></label></div><div class="two"><label>Email<input type="email" name="email"></label><label>Lead time (days)<input type="number" name="lead_time_days"></label></div><label>Payment terms<input name="payment_terms" placeholder="30 days"></label><label>Address<textarea name="address"></textarea></label><label>Notes<textarea name="notes"></textarea></label><button class="btn primary">Add supplier</button></form></section><section class="staff-panel"><h2>Supplier overview</h2><div class="module-grid"><div class="metric-card"><small>Active suppliers</small><strong><?=count(array_filter($rows,fn($x)=>(int)$x['is_active']===1))?></strong></div><div class="metric-card"><small>Purchase orders</small><strong><?=array_sum(array_column($rows,'po_count'))?></strong></div></div></section></div><section class="staff-panel table-panel"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Terms</th><th>Lead time</th><th>POs</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['company_name'])?></b><small><?=h($r['supplier_code'])?></small></td><td><?=h($r['contact_person']?:'—')?><small><?=h($r['phone']?:$r['email'])?></small></td><td><?=h($r['payment_terms']?:'—')?></td><td><?=h($r['lead_time_days']!==null?$r['lead_time_days'].' days':'—')?></td><td><?=$r['po_count']?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>